"""Realistic synthetic data, step 1/3 (main venv): watermarked base images + regions to be GENERATED by inpainting.
    python inp_prep.py --method trustmark --shard 0 --n 400
Kinds (25 % each): removal (own COCO object inpainted away, empty prompt), addition (random object shape inpainted with
a COCO category prompt), outpaint (small watermarked rectangle, everything around it generated), transplant (as synth.py).
Writes results/synth_inp/<method>_<shard>/prep.npz: base (N,512,512,3), gen (N,512,512) region to generate,
label (N,128,128), prompt, kind, message."""
import argparse, time
from pathlib import Path
import numpy as np
from PIL import Image
import data
from synth import Coco, S, transplant
from wmloc.utils import downsample_mask
from wmloc.watermarks import load_watermark

ap = argparse.ArgumentParser(); ap.add_argument("--method", required=True); ap.add_argument("--shard", type=int, default=0); ap.add_argument("--n", type=int, default=400)
a = ap.parse_args()
rng = np.random.default_rng(777 + 1000 * data.METHODS.index(a.method) + a.shard)
wm = load_watermark(a.method, models_dir=data.TASK_DIR / "models", device="cuda"); co = Coco(rng)
cats = [c["name"] for c in co.c.loadCats(co.c.getCatIds())]
max_aspect = 2.0 if a.method == "trustmark" else 16.0
B = np.zeros((a.n, S, S, 3), np.uint8); Gm = np.zeros((a.n, S, S), bool); L = np.zeros((a.n, 128, 128), np.uint8)
prompts, kinds, msgs = [], [], []; t0 = time.time()
for i in range(a.n):
    bits = rng.integers(0, 2, wm.nbits); u = rng.random(); prompt = ""
    if u < 0.5:                                                   # holes: removal / addition (full regime)
        canvas, crop = co.canvas(); wa = wm.embed(canvas, bits)
        if u < 0.25:
            own = co.object_masks(crop, 0.002, 0.3); kind = "removal"
            ms = [own[j] for j in rng.permutation(len(own))[:rng.integers(1, 3)]] if own else []
        else:
            ms = []; kind = "addition"; prompt = f"a photo of a {cats[rng.integers(len(cats))]}"
        while not ms:
            m = co.random_object(max_frac=0.3)
            if m is not None:
                ms.append(m)
        gen = np.any(ms, 0)
        gen = np.asarray(Image.fromarray(gen.astype(np.uint8) * 255).filter(__import__("PIL.ImageFilter").ImageFilter.MaxFilter(5))) > 127
        base, lab = wa, ~gen
    elif u < 0.75:                                                # outpaint: rectangle kept, the rest generated
        kind = "outpaint"; i_ = int(rng.choice(co.ids)); im = co.image(i_); H, W = im.shape[:2]
        asp = np.exp(rng.uniform(0, np.log(max_aspect))); asp = 1 / asp if rng.random() < 0.5 else asp
        ch = int(min(H, W / asp) * rng.uniform(0.5, 1.0)); cw = max(8, int(ch * asp)); ch = max(8, ch)
        y, x = rng.integers(0, H - ch + 1), rng.integers(0, W - cw + 1); src = np.ascontiguousarray(im[y:y + ch, x:x + cw])
        wsrc = wm.embed(src, bits)
        for _ in range(50):
            frac = np.exp(rng.uniform(np.log(0.004), np.log(0.35))); th = int(round(np.sqrt(frac * S * S / asp))); tw = int(round(th * asp))
            if 8 <= th <= S and 8 <= tw <= S:
                break
        th, tw = min(max(th, 8), S), min(max(tw, 8), S)
        ty, tx = rng.integers(0, S - th + 1), rng.integers(0, S - tw + 1)
        base = np.asarray(Image.fromarray(src).resize((S, S), Image.BICUBIC)).copy()          # init outside (gets regenerated)
        base[ty:ty + th, tx:tx + tw] = np.asarray(Image.fromarray(wsrc).resize((tw, th), Image.LANCZOS))
        lab = np.zeros((S, S), bool); lab[ty:ty + th, tx:tx + tw] = True; gen = ~lab
    else:                                                         # transplant (unchanged recipe)
        base, lab8, kind = transplant(wm, co, rng, bits); lab = lab8.astype(bool); gen = np.zeros((S, S), bool)
    B[i], Gm[i], L[i] = base, gen, downsample_mask(lab.astype(np.uint8))
    prompts.append(prompt); kinds.append(kind); msgs.append("".join(map(str, bits)))
    if i % 100 == 0:
        print(i, f"{time.time() - t0:.0f}s", flush=True)
d = data.RESULTS / "synth_inp" / f"{a.method}_{a.shard}"; d.mkdir(parents=True, exist_ok=True)
np.savez(d / "prep.npz", base=B, gen=Gm, label=L, prompt=np.array(prompts), kind=np.array(kinds), message=np.array(msgs))
print("prep done", f"{time.time() - t0:.0f}s")
